            ],
            'intelligence' => [
                'title' => 'Intelligence & Analytics',
                'icon'  => 'fas fa-chart-pie',
                'tools' => []
            ],
            'knowledge' => [
                'title' => 'Knowledge & Prompts',
                'icon'  => 'fas fa-book-open',
                'tools' => []
            ],
            'automation' => [
                'title' => 'Automation & Ops',
                'icon'  => 'fas fa-robot',
                'tools' => []
