        <script>
        function switchSettingsSection(tabId, btn) {
            document.querySelectorAll('.sdv-settings-pane').forEach(function(pane) {
                pane.style.display = 'none';
            });
            document.querySelectorAll('.sdv-settings-tab-btn').forEach(function(b) {
                b.classList.remove('active', 'btn-primary');
                b.classList.add('btn-default');
            });
            var target = document.getElementById(tabId);
            if (target) target.style.display = 'block';
            btn.classList.remove('btn-default');
            btn.classList.add('active', 'btn-primary');
        }

        function sendTestFirebasePush() {
            var btn = document.getElementById('btn-sdv-test-push');
            var statusSpan = document.getElementById('sdv-test-push-status');
            if (!btn) return;
            btn.disabled = true;
            btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Dispatching...';
            statusSpan.style.color = '#64748b';
            statusSpan.textContent = 'Sending test notification via FCM HTTP v1...';

            var data = new URLSearchParams();
            data.append('action', 'admin_test_firebase_push');

            fetch('addonmodules.php?module=sahdev&action=admin_test_firebase_push', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                    'Accept': 'application/json'
                },
                body: data.toString()
            })
            .then(function(res) { return res.json(); })
            .then(function(json) {
                btn.disabled = false;
                btn.innerHTML = '<i class="fas fa-paper-plane"></i> Send Test Push to Staff Devices';
                if (json.status === 'success') {
                    statusSpan.style.color = '#16a34a';
                    statusSpan.innerHTML = '<i class="fas fa-check-circle"></i> ' + (json.message || 'Push sent successfully!');
                } else {
                    statusSpan.style.color = '#dc2626';
                    statusSpan.innerHTML = '<i class="fas fa-exclamation-circle"></i> ' + (json.message || 'Push failed');
                }
            })
            .catch(function(err) {
                btn.disabled = false;
                btn.innerHTML = '<i class="fas fa-paper-plane"></i> Send Test Push to Staff Devices';
                statusSpan.style.color = '#dc2626';
                statusSpan.innerHTML = '<i class="fas fa-times-circle"></i> Network error: ' + err.message;
            });
        }
        </script>
        <?php
        return ob_get_clean();
    }

    /**
     * AI Providers Manager View
     *
     * @return string
     */
    public function providers()
    {
        $successMessage = '';
        $errorMessage = '';

        require_once dirname(__DIR__) . '/lib/SchemaManager.php';
        \Sahdev\Lib\SchemaManager::ensureProviderColumns();
        \Sahdev\Lib\SchemaManager::ensureSettingsColumns();

        if ($_SERVER['REQUEST_METHOD'] === 'POST') {
            check_token("WHMCS.admin.default");

            $action = $_POST['provider_action'] ?? '';

            if ($action === 'create' || $action === 'update') {
                $id = (int) ($_POST['provider_id'] ?? 0);
                $name = trim($_POST['provider_name'] ?? '');
                $type = $_POST['provider_type'] ?? 'openrouter';
                $purpose = $_POST['provider_purpose'] ?? 'both';
                $apiKey = $_POST['api_key'] ?? '';
                $apiUrl = $_POST['api_url'] ?? '';
                $modelName = $_POST['model_name'] ?? '';
                $costInput = (float) ($_POST['cost_input_1m'] ?? 0.0000);
                $costOutput = (float) ($_POST['cost_output_1m'] ?? 0.0000);

                if (empty($name)) {
                    $errorMessage = "Provider name is required.";
                } else {
                    $data = [
                        'name'          => $name,
                        'provider_type' => $type,
                        'purpose'       => $purpose,
                        'api_url'       => $apiUrl,
                        'model_name'    => $modelName,
                        'cost_input_1m' => $costInput,
                        'cost_output_1m'=> $costOutput,
                        'updated_at'    => \Carbon\Carbon::now(),
                    ];

                    if (!empty($apiKey)) {
                        $data['api_key'] = encrypt($apiKey);
                    }

                    if ($action === 'create') {
                        $data['created_at'] = \Carbon\Carbon::now();
                        Capsule::table('tblsahdev_providers')->insert($data);
                        $successMessage = "Provider created successfully.";
                    } else {
                        Capsule::table('tblsahdev_providers')->where('id', $id)->update($data);
                        $successMessage = "Provider updated successfully.";
                    }
                }
            } elseif ($action === 'delete') {
                $id = (int) $_POST['provider_id'];

                $inUse = Capsule::table('tblsahdev_settings')
                    ->where('primary_provider_id', $id)
                    ->orWhere('fallback_provider_id', $id)
                    ->orWhere('copilot_primary_provider_id', $id)
                    ->orWhere('copilot_fallback_provider_id', $id)
                    ->exists();

                if ($inUse) {
                    $errorMessage = "Cannot delete provider while it is assigned as Primary or Fallback.";
                } else {
                    Capsule::table('tblsahdev_providers')->where('id', $id)->delete();
                    $successMessage = "Provider deleted.";
                }
            } elseif ($action === 'save_assignments' || $action === 'save_chat_settings') {
                $primaryId = (int) ($_POST['primary_provider_id'] ?? 0);
                $fallbackId = (int) ($_POST['fallback_provider_id'] ?? 0);
                $copilotId = (int) ($_POST['copilot_primary_provider_id'] ?? 0);
                $copilotFallbackId = (int) ($_POST['copilot_fallback_provider_id'] ?? 0);
                $clientChatId = (int) ($_POST['client_chat_provider_id'] ?? 0);

                $updateData = [];
                if (isset($_POST['primary_provider_id'])) {
                    $updateData['primary_provider_id'] = $primaryId > 0 ? $primaryId : 1;
                }
                if (isset($_POST['fallback_provider_id'])) {
                    $updateData['fallback_provider_id'] = $fallbackId;
                }
                if (isset($_POST['copilot_primary_provider_id'])) {
                    $updateData['copilot_primary_provider_id'] = $copilotId;
                }
                if (isset($_POST['copilot_fallback_provider_id'])) {
                    $updateData['copilot_fallback_provider_id'] = $copilotFallbackId;
                }
                if (isset($_POST['client_chat_provider_id'])) {
                    $updateData['client_chat_provider_id'] = $clientChatId;
                }
                if (isset($_POST['copilot_temperature'])) {
                    $updateData['copilot_temperature'] = (float) $_POST['copilot_temperature'];
                }
                if (isset($_POST['copilot_max_tokens'])) {
                    $updateData['copilot_max_tokens'] = (int) $_POST['copilot_max_tokens'];
                }
                if (isset($_POST['copilot_stream_submitted'])) {
                    $updateData['copilot_stream_enabled'] = !empty($_POST['copilot_stream_enabled']) ? 1 : 0;
                }
                if (isset($_POST['copilot_system_prompt'])) {
                    $updateData['copilot_system_prompt'] = trim($_POST['copilot_system_prompt']);
                }
                if (isset($_POST['task_provider_map']) && is_array($_POST['task_provider_map'])) {
                    $taskProviderMap = [];
                    foreach (TaskProviderResolver::canonicalTaskKeys() as $key) {
                        if (!isset($_POST['task_provider_map'][$key])) {
                            continue;
                        }
                        $vid = (int) $_POST['task_provider_map'][$key];
                        if ($vid > 0 && TaskProviderResolver::isValidActiveProviderId($vid)) {
                            $taskProviderMap[$key] = $vid;
                        }
                    }
                    $updateData['task_provider_map'] = $taskProviderMap === [] ? null : json_encode($taskProviderMap);
                }

                $updateData['updated_at'] = \Carbon\Carbon::now();
                Capsule::table('tblsahdev_settings')->where('id', 1)->update($updateData);
                $successMessage = "AI Provider role assignments and orchestration saved successfully.";
            }
        }

        $providers = Capsule::table('tblsahdev_providers')->get();
        $settings = Capsule::table('tblsahdev_settings')->first();
        $taskMapStored = TaskProviderResolver::parseTaskProviderMap($settings->task_provider_map ?? null);

        $csrfToken = generate_token("form");
        $actionUrl = htmlspecialchars($this->moduleVars['modulelink']) . '&action=providers';

        ob_start();
