                                    <?php else: ?>
                                        <span class="ap-log-skipped"><i class="fas fa-minus-circle"></i> <?php echo htmlspecialchars($log->ai_decision); ?></span>
                                    <?php endif; ?>
                                </td>
                                <td><?php echo htmlspecialchars($log->skip_reason ?? '—'); ?></td>
