                        <pre class="modal-content-pre" id="logViewRawOutput"></pre>
                    </div>
                </div>
            </div>
        </div>

        <script>
        function viewLogModal(el) {
            var rawBase64 = el.getAttribute('data-full');
            var rawText = '';
            try {
                // b64 decode
                rawText = decodeURIComponent(escape(window.atob(rawBase64)));
                // Attempt JSON prettify
                var parsed = JSON.parse(rawText);
                rawText = JSON.stringify(parsed, null, 2);
            } catch (e) {
                // Keep raw text if not JSON or decode fails
            }
            document.getElementById('logViewRawOutput').textContent = rawText;
            $('#logViewModal').modal('show');
        }
        </script>

        <?php
        return ob_get_clean();
    }

    /**
     * Incident & Server Monitoring Center Dashboard
     */
    public function incidents(): string
    {
        $adminId = (int) ($_SESSION['adminid'] ?? 0);
        require_once dirname(__DIR__) . '/lib/ServerTelemetryService.php';
        require_once dirname(__DIR__) . '/lib/IncidentDetectionService.php';
        require_once dirname(__DIR__) . '/lib/PermissionService.php';
        \Sahdev\Lib\PermissionService::ensureSchema();

        $canViewTelemetry = \Sahdev\Lib\PermissionService::hasPermission($adminId, \Sahdev\Lib\PermissionService::PERM_TELEMETRY_VIEW);
        $canManageIncidents = \Sahdev\Lib\PermissionService::hasPermission($adminId, \Sahdev\Lib\PermissionService::PERM_INCIDENTS_MANAGE);
        $canAccessServer = \Sahdev\Lib\PermissionService::hasPermission($adminId, \Sahdev\Lib\PermissionService::PERM_SERVER_ACCESS);
        $canManageSettings = \Sahdev\Lib\PermissionService::hasPermission($adminId, \Sahdev\Lib\PermissionService::PERM_SETTINGS_MANAGE);

        if (!$canViewTelemetry && !$canManageIncidents) {
            return $this->getNavigationMarkup('incidents') . '<div class="alert alert-danger" style="margin:20px;"><i class="fas fa-lock"></i> Access Denied: Your WHMCS admin role does not have permission to access Incident & Server Monitoring.</div>';
        }

        $actionUrl = htmlspecialchars($this->moduleVars['modulelink']) . '&action=incidents';
        $csrfToken = generate_token("form");
        $successMessage = '';
        $errorMessage = '';

        // Handle POST Actions
        if ($_SERVER['REQUEST_METHOD'] === 'POST') {
            check_token("form");

            if (isset($_POST['trigger_server_poll']) && ($canViewTelemetry || $canManageIncidents)) {
                try {
                    $pollRes = \Sahdev\Lib\ServerTelemetryService::pollActiveServers(true);
                    $successMessage = "Polled {$pollRes['polled']} server(s) successfully.";
                } catch (\Throwable $e) {
                    $errorMessage = "Error polling servers: " . $e->getMessage();
                }
            } elseif (isset($_POST['trigger_cluster_eval']) && $canManageIncidents) {
                try {
                    $evalRes = \Sahdev\Lib\IncidentDetectionService::evaluateClusters();
                    $successMessage = "Incident evaluation completed. Scanned {$evalRes['tickets_scanned']} ticket(s), found {$evalRes['clusters_found']} cluster(s).";
                } catch (\Throwable $e) {
                    $errorMessage = "Error evaluating incidents: " . $e->getMessage();
                }
            } elseif (isset($_POST['update_incident_status']) && $canManageIncidents) {
                $incId = (int) ($_POST['incident_id'] ?? 0);
                $newStatus = trim((string) ($_POST['new_status'] ?? 'Active'));
                if ($incId > 0 && in_array($newStatus, ['Active', 'Investigating', 'Monitoring', 'Resolved'])) {
                    $upData = ['status' => $newStatus, 'updated_at' => \Carbon\Carbon::now()];
                    if ($newStatus === 'Resolved') {
                        $upData['resolved_at'] = \Carbon\Carbon::now();
                    }
                    Capsule::table('tblsahdev_incidents')->where('id', $incId)->update($upData);
                    $successMessage = "Incident #{$incId} status updated to {$newStatus}.";
                }
            } elseif (isset($_POST['apply_broadcast_reply']) && $canManageIncidents) {
                $incId = (int) ($_POST['incident_id'] ?? 0);
                $replyBody = trim((string) ($_POST['broadcast_message'] ?? ''));
                $inc = Capsule::table('tblsahdev_incidents')->where('id', $incId)->first();
                if ($inc && $replyBody !== '') {
                    $ticketIds = !empty($inc->ticket_ids_json) ? json_decode($inc->ticket_ids_json, true) : [];
                    $repliedCount = 0;
                    $adminUser = 'System';
                    try {
                        $adminUser = Capsule::table('tbladmins')->where('id', (int) ($_SESSION['adminid'] ?? 1))->value('username') ?: 'System';
                    } catch (\Throwable $e) {}

                    foreach ($ticketIds as $tid) {
                        try {
                            Capsule::table('tblticketreplies')->insert([
                                'tid' => (int) $tid,
                                'admin' => $adminUser,
                                'date' => \Carbon\Carbon::now(),
                                'message' => $replyBody,
                                'rating' => 0,
                            ]);
                            Capsule::table('tbltickets')->where('id', (int) $tid)->update([
                                'status' => 'Answered',
                                'lastreply' => \Carbon\Carbon::now(),
                            ]);
                            $repliedCount++;
                        } catch (\Throwable $e) {}
                    }
                    $successMessage = "Broadcast reply posted to {$repliedCount} ticket(s) under Incident {$inc->incident_num}.";
                }
            } elseif (isset($_POST['save_server_monitoring']) && ($canManageSettings || $canManageIncidents)) {
                $monitoredInput = (array) ($_POST['monitored_servers'] ?? []);
                $rolesInput = (array) ($_POST['server_roles'] ?? []);

                $allDbServers = Capsule::table('tblservers')->where('disabled', 0)->get();
                foreach ($allDbServers as $srvObj) {
                    $srvId = (int) $srvObj->id;
                    $isMon = isset($monitoredInput[$srvId]) ? 1 : 0;
                    $roleVal = (string) ($rolesInput[$srvId] ?? 'auto');
                    if (!in_array($roleVal, ['auto', 'root', 'reseller', 'vps_node', 'plesk', 'directadmin'])) {
                        $roleVal = 'auto';
                    }

                    Capsule::table('tblsahdev_server_telemetry')->updateOrInsert(
                        ['server_id' => $srvId],
                        [
                            'server_name' => (string) ($srvObj->name ?? 'Server #' . $srvId),
                            'server_host' => (string) ($srvObj->hostname ?: $srvObj->ipaddress),
                            'server_type' => (string) ($srvObj->type ?? 'cpanel'),
                            'server_role' => $roleVal,
                            'is_monitored' => $isMon,
                            'updated_at' => \Carbon\Carbon::now(),
                        ]
                    );
                }
                $successMessage = "Server monitoring settings and role assignments saved successfully.";
            }
        }

        // Fetch Incidents
        $activeIncidents = Capsule::table('tblsahdev_incidents')
            ->whereIn('status', ['Active', 'Investigating', 'Monitoring'])
            ->orderBy('id', 'desc')
            ->get();

        $resolvedIncidents = Capsule::table('tblsahdev_incidents')
            ->where('status', 'Resolved')
            ->orderBy('id', 'desc')
            ->limit(10)
            ->get();

        // Fetch Server Telemetry
        \Sahdev\Lib\ServerTelemetryService::ensureSchema();
        try {
            $servers = Capsule::table('tblservers as s')
                ->leftJoin('tblsahdev_server_telemetry as st', 's.id', '=', 'st.server_id')
                ->where('s.disabled', 0)
                ->select(
                    's.id as server_id',
                    's.name as server_name',
                    's.hostname',
                    's.ipaddress',
                    's.type as server_type',
                    's.username',
                    Capsule::raw('COALESCE(st.server_role, "auto") as server_role'),
                    Capsule::raw('COALESCE(st.is_monitored, 1) as is_monitored'),
                    'st.server_load',
                    'st.is_reachable',
                    'st.reachability_error',
                    'st.accounts_data_json',
                    'st.server_stats_json',
                    'st.last_polled_at'
                )
                ->get();
        } catch (\Throwable $ex) {
            \Sahdev\Lib\ServerTelemetryService::ensureSchema();
            $servers = Capsule::table('tblservers as s')
                ->leftJoin('tblsahdev_server_telemetry as st', 's.id', '=', 'st.server_id')
                ->where('s.disabled', 0)
                ->select(
                    's.id as server_id',
                    's.name as server_name',
                    's.hostname',
                    's.ipaddress',
                    's.type as server_type',
                    's.username',
                    'st.server_load',
                    'st.is_reachable',
                    'st.reachability_error',
                    'st.accounts_data_json',
                    'st.server_stats_json',
                    'st.last_polled_at'
                )
                ->get();
        }

        $totalServers = $servers->count();
        $monitoredServersCount = $servers->filter(function($s) { return !isset($s->is_monitored) || (int)$s->is_monitored === 1; })->count();
        $reachableServers = $servers->where('is_reachable', 1)->count();
        $totalIncidentsCount = $activeIncidents->count();

        ob_start();
        ?>
        <div class="sahdev-container">
            <?php echo $this->getNavigationMarkup('incidents'); ?>

            <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 20px;">
                <div>
                    <h2 style="margin: 0; font-size: 22px; color: #1a202c; font-weight: 700;">
                        <i class="fas fa-satellite-dish" style="color: #20c997;"></i> Incident & Server Monitoring Center
                    </h2>
                    <p class="text-muted" style="margin: 5px 0 0 0; font-size: 13px;">
                        Real-time reseller-safe server health, automated outage surge detection, and 1-click broadcast replies.
                    </p>
                </div>
                <div style="display: flex; gap: 10px;">
                    <?php if ($canManageSettings || $canManageIncidents): ?>
                        <button type="button" class="btn btn-default btn-sm" data-toggle="modal" data-target="#modalServerMonitoring">
                            <i class="fas fa-sliders-h"></i> Manage Servers & Roles
                        </button>
                    <?php endif; ?>
                    <form method="post" action="<?php echo $actionUrl; ?>" style="display:inline;">
                        <?php echo $csrfToken; ?>
                        <button type="submit" name="trigger_server_poll" value="1" class="btn btn-primary btn-sm">
                            <i class="fas fa-sync-alt"></i> Poll Servers Now
                        </button>
                    </form>
                    <?php if ($canManageIncidents): ?>
                        <form method="post" action="<?php echo $actionUrl; ?>" style="display:inline;">
                            <?php echo $csrfToken; ?>
                            <button type="submit" name="trigger_cluster_eval" value="1" class="btn btn-success btn-sm">
                                <i class="fas fa-search"></i> Scan Incident Surges
                            </button>
                        </form>
                    <?php endif; ?>
                </div>
            </div>

            <?php if ($successMessage): ?>
                <div class="alert alert-success alert-dismissible" role="alert" style="margin-bottom: 20px;">
                    <button type="button" class="close" data-dismiss="alert"><span aria-hidden="true">&times;</span></button>
                    <i class="fas fa-check-circle"></i> <?php echo htmlspecialchars($successMessage); ?>
                </div>
            <?php endif; ?>

            <?php if ($errorMessage): ?>
                <div class="alert alert-danger alert-dismissible" role="alert" style="margin-bottom: 20px;">
                    <button type="button" class="close" data-dismiss="alert"><span aria-hidden="true">&times;</span></button>
                    <i class="fas fa-exclamation-triangle"></i> <?php echo htmlspecialchars($errorMessage); ?>
                </div>
            <?php endif; ?>

            <!-- Metrics Overview -->
            <div class="row" style="margin-bottom: 20px;">
                <div class="col-md-4">
                    <div style="background: #fff; border: 1px solid #e2e8f0; border-left: 4px solid #e53e3e; border-radius: 6px; padding: 15px;">
                        <div style="font-size: 11px; text-transform: uppercase; color: #718096; font-weight: 700;">Active Incidents</div>
                        <div style="font-size: 24px; font-weight: 800; color: #1a202c; margin: 4px 0;">
                            <?php echo $totalIncidentsCount; ?>
                        </div>
                        <div style="font-size: 12px; color: #718096;">
                            <?php echo $totalIncidentsCount === 0 ? 'All systems operating normally' : "{$totalIncidentsCount} active event(s) detected"; ?>
                        </div>
                    </div>
                </div>
                <div class="col-md-4">
                    <div style="background: #fff; border: 1px solid #e2e8f0; border-left: 4px solid #3182ce; border-radius: 6px; padding: 15px;">
                        <div style="font-size: 11px; text-transform: uppercase; color: #718096; font-weight: 700;">Monitored Servers</div>
                        <div style="font-size: 24px; font-weight: 800; color: #1a202c; margin: 4px 0;">
                            <?php echo $reachableServers; ?> / <?php echo $monitoredServersCount; ?> <span style="font-size: 13px; font-weight: normal; color: #718096;">(Total: <?php echo $totalServers; ?>)</span>
                        </div>
                        <div style="font-size: 12px; color: #718096;">
                            Reachable & responsive
                        </div>
                    </div>
                </div>
                <div class="col-md-4">
                    <div style="background: #fff; border: 1px solid #e2e8f0; border-left: 4px solid #805ad5; border-radius: 6px; padding: 15px;">
                        <div style="font-size: 11px; text-transform: uppercase; color: #718096; font-weight: 700;">Multi-Panel Telemetry</div>
                        <div style="font-size: 16px; font-weight: 700; color: #2d3748; margin: 8px 0;">
